parameters.jsCode:
const raw = String($input.first().json.choices?.[0]?.message?.content ?? '').replace(/\\n/g, '\n').replace(/\r/g, '');
const lines = raw.split('\n').map(s => s.trim()).filter(Boolean);
const slides = [];
for (const line of lines) {
  const match = line.match(/^(?:ال)?سلايد\s*([1-7])\s*[:：-]\s*(.*)$/i);
  if (match) {
    slides.push({number: Number(match[1]), title: match[2].replace(/^(?:العنوان|هوك قوي)\s*[-:：]\s*/,'').trim(), body: ''});
  } else if (slides.length && !slides[slides.length-1].body) {
    slides[slides.length-1].body = line.replace(/^(?:الشرح|الجملة التوضيحية)\s*[-:：]\s*/,'').trim();
  }
}
if (slides.length !== 7 || slides.some((s,i)=>s.number!==i+1 || !s.title)) {
 throw new Error('Expected 7 numbered slides with titles and descriptions; review Groq response before design generation.');
}
return slides.map(s => ({json:{slideNumber:s.number,title:s.title,body:s.body,width:1080,height:1920,format:'png',topic:$('Prepare Topic').first().json.topic,chatId:$('Prepare Topic').first().json.chatId}}));

const item = $input.item.json;
const esc = v => String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const n = Number(item.slideNumber);
const title = esc(item.title);
const body = esc(item.body);
const topicLabel = esc(String(item.topic ?? "").trim().replace(/\s+/g," ").slice(0,48));
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920" viewBox="0 0 1080 1920">
<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#0B1235"/><stop offset=".55" stop-color="#30205E"/><stop offset="1" stop-color="#8C256D"/></linearGradient></defs>
<rect width="1080" height="1920" fill="url(#bg)"/>
<circle cx="920" cy="240" r="330" fill="#EC4899" opacity=".12"/>
<circle cx="140" cy="1520" r="350" fill="#38BDF8" opacity=".10"/>
<rect x="70" y="95" width="940" height="1730" rx="55" fill="#FFFFFF" fill-opacity=".07" stroke="#FFFFFF" stroke-opacity=".20" stroke-width="3"/>
<foreignObject x="130" y="150" width="800" height="180"><div xmlns="http://www.w3.org/1999/xhtml" dir="rtl" style="font-family:Arial,sans-serif;color:#D8B4FE;text-align:right;font-size:39px;font-weight:700;overflow-wrap:break-word">${topicLabel}</div></foreignObject>
<foreignObject x="120" y="490" width="840" height="900"><div xmlns="http://www.w3.org/1999/xhtml" dir="rtl" style="font-family:Arial,'Noto Sans Arabic',sans-serif;color:white;text-align:right;overflow-wrap:break-word"><div style="font-size:79px;font-weight:800;line-height:1.45;margin-bottom:75px">${title}</div><div style="font-size:52px;line-height:1.7;color:#E5E7EB">${body}</div></div></foreignObject>
<rect x="120" y="1660" width="840" height="4" rx="2" fill="#F472B6"/>
</svg>`;
return {json:{...item,svg,svgFilename:'006-slide-'+String(n).padStart(2,'0')+'.svg',renderStatus:'SVG source only — PNG conversion not yet connected'}};
